import type { SerializedEditorState } from '@payloadcms/richtext-lexical/lexical'
import {
  RichText as PayloadRichText,
  type JSXConverters,
} from '@payloadcms/richtext-lexical/react'

/**
 * Shape of a Payload rich-text field as generated by `payload generate:types`.
 *
 * The generated type for every `richText` field is structurally identical to
 * Lexical's {@link SerializedEditorState} (a `root` object with `children`),
 * but Payload also adds an index signature (`[k: string]: unknown`) and uses
 * `any` for child node `type`. The shape is therefore a strict supertype of
 * `SerializedEditorState` — assignable in either direction with a narrow cast.
 *
 * Rather than re-declare the structure by hand (which would drift from
 * `generate:types`), we alias `SerializedEditorState` and treat the small
 * widening from Payload's generated type as a structural compatibility cast
 * performed once inside {@link RichText}.
 */
export type RichTextContent = SerializedEditorState

/**
 * Props for the {@link RichText} renderer.
 *
 * `content` accepts `null | undefined` so callers can write
 * `<RichText content={page.intro?.body} />` without a defensive guard.
 *
 * `converters` and `className` are forwarded to the underlying Payload
 * {@link PayloadRichText} renderer for callers that need custom node
 * rendering or container styling.
 */
export interface RichTextProps {
  content: RichTextContent | null | undefined
  converters?: JSXConverters
  className?: string
}

/**
 * Render Payload Lexical rich-text content as JSX.
 *
 * Thin wrapper around `@payloadcms/richtext-lexical/react`'s `RichText`.
 * The wrapper exists so every page/block can call `<RichText content={…} />`
 * without repeating the `null` guard, the type cast from Payload's generated
 * rich-text shape to Lexical's `SerializedEditorState`, and the standard
 * converter wiring.
 *
 * The renderer is a Server Component by default — it does not pull in any
 * client-only Lexical editor state. It uses the JSX converter pipeline.
 */
export function RichText({ content, converters, className }: RichTextProps) {
  if (!content) return null

  return (
    <PayloadRichText
      data={content}
      converters={converters}
      className={className}
    />
  )
}

export default RichText
